import pandas as pd
import numpy as np

# Load the transport data
transport_data = pd.read_csv('chunks_csv/getisord/getisord_2021_transport.csv')
# Load the adjacency data
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Check for missing values
assert transport_data['Transport_value'].isnull().sum() == 0, "There are missing values in the transport data."

# Step 3: Define Local Areas
# Create a dictionary to hold combined transport values for each borough
local_areas = {}

# Populate the local areas with the borough itself and its neighbors
for _, row in adjacency_data.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']

    if borough not in local_areas:
        local_areas[borough] = [borough]
    if neighbor not in local_areas:
        local_areas[neighbor] = [neighbor]

    local_areas[borough].append(neighbor)

# Step 4: Calculate Combined Transport Values
combined_transport_values = {}
for borough, areas in local_areas.items():
    combined_value = transport_data[transport_data['borough'].isin(areas)]['Transport_value'].sum()
    combined_transport_values[borough] = combined_value

# Step 5: Compute Citywide Average
citywide_average = transport_data['Transport_value'].mean()
citywide_std = transport_data['Transport_value'].std()

# Step 6: Calculate Z-scores
z_scores = {}
for borough, combined_value in combined_transport_values.items():
    z_score = (combined_value - citywide_average) / citywide_std
    z_scores[borough] = z_score

# Step 7: Identify Hot and Cold Spots
hot_spots = {}
cold_spots = {}
for borough, z_score in z_scores.items():
    if z_score > 1.96:
        hot_spots[borough] = z_score
    elif z_score < -1.96:
        cold_spots[borough] = z_score

# Step 9: Count Data Points Used
data_points_used = len(transport_data)

# Prepare results
results = []
for borough, z_score in hot_spots.items():
    results.append(f"{borough} (HOT, Gi*={z_score:.4f}, gi_value={z_score:.4f})")
for borough, z_score in cold_spots.items():
    results.append(f"{borough} (COLD, Gi*={z_score:.4f}, gi_value={z_score:.4f})")

# Output results
print(f"data_points_used = {data_points_used}")
if results:
    print(f"FINAL ANSWER: {', '.join(results)}")
else:
    print("FINAL ANSWER: none")
